import subprocess, json
def infer(path):
    inp=json.dumps({"Path":path,"Version":"v1"})
    p=subprocess.run(["./executable"],input=inp.encode(),capture_output=True)
    lines=p.stdout.decode().splitlines()
    hdrseg=lines[0].split('+')[1]
    rowseg=lines[3].split('|')[1]
    rest=rowseg[1:]
    trailing=len(rest)-len(rest.rstrip(' '))
    return (len(hdrseg)-2)-(trailing-1)
for param in ["12345","1;234","12;34;56","0;0","999;999","1;2;3;4;5"]:
    print(param, infer(f"ab\x1b[{param}m"), infer(f"ab\x1b[{param}K"))
for final in ["m","K","J","H","f","s","u","L","M"]:
    print(final, infer(f"ab\x1b[31{final}"))
# intermediate chars
for s in ["\x1b[31m","\x1b[38;5;196m","\x1b[38;2;1;2;3m"]:
    print(repr(s), infer("ab"+s))
PY"}

