				b.WriteString(padCell(text, widths[j], false))
				b.WriteString("|")
			}
			b.WriteString("\n")
		}
	}
	if !markdown {
		borderLine("+", "-", "+", "+")
	}
	_, _ = io.WriteString(output, b.String())
}

func padCell(text string, width int, header bool) string {
	segmentWidth := width + 2
	textWidth := displayWidth(text)
	if header {
		total := segmentWidth - textWidth
		if total < 0 {
			total = 0
		}
		left := total / 2
		right := total - left
		return strings.Repeat(" ", left) + text + strings.Repeat(" ", right)
	}
	right := segmentWidth - 1 - textWidth
	if right < 0 {
		right = 0
	}
	return " " + text + strings.Repeat(" ", right)
}

// wrapCell reflows a cell so that none of its lines is wider than the
// longest line in the original cell, capped at maxColumnWidth.
func wrapCell(cell string) []string {
	paragraphs := strings.Split(cell, "\n")
	limit := 0
	for _, paragraph := range paragraphs {
		if w := displayWidth(paragraph); w > limit {
			limit = w
		}
	}
	if limit > maxColumnWidth {
		limit = maxColumnWidth
	}
	joined := strings.ReplaceAll(cell, "\n", " ")
	words := strings.Split(joined, " ")
	var lines []string
	var current []string
	currentWidth := 0
	for i, word := range words {
		wordWidth := displayWidth(word)
		if i == 0 {
			current = []string{word}
			currentWidth = wordWidth
			continue
		}
		if currentWidth+1+wordWidth > limit {
			lines = append(lines, strings.Join(current, " "))
			current = []string{word}
			currentWidth = wordWidth
		} else {
			current = append(current, word)
			currentWidth += 1 + wordWidth
		}
	}
	lines = append(lines, strings.Join(current, " "))
	return lines
}

func displayWidth(s string) int {
	if strings.Contains(s, "\x1b") {
		s = ansiPattern.ReplaceAllString(s, "")
	}
	width := 0
	for _, r := range s {
		width += runeWidth(r)
	}
	return width
}

func runeWidth(r rune) int {
	switch {
	case r == 0:
		return 0
	case r < 0x20:
		return 0
	case r >= 0x7f && r <= 0x9f:
		return 0
	case r == 0x00ad:
		return 1
	case r == 0x200b, r == 0x200c, r == 0x200d, r == 0x2060, r == 0xfeff:
		return 0
	case unicode.Is(unicode.Mn, r), unicode.Is(unicode.Me, r):
		return 0
	case r >= 0xfe00 && r <= 0xfe0f:
		return 0
	case r >= 0xe0100 && r <= 0xe01ef:
		return 0
	}
	if isWideRune(r) {
		return 2
	}
	return 1
}

